          "path": "js/sandbox.js",
          "name": "sandbox.js",
          "size": 4436,
          "language": "javascript",
          "content": "/**\n * Targets Sandbox Module\n * Manages simulated vulnerable target profiles.\n * Allows toggling vulnerabilities and custom configurations.\n */\n\nconst TargetsSandbox = (() => {\n  const STORAGE_KEY = 'vulnscanner_sandbox';\n\n  // Default sandbox target profiles\n  const DEFAULT_PROFILES = {\n    metasploitable: {\n      id: 'metasploitable',\n      name: 'Metasploitable 2 (Vulnerable Sim)',\n      ip: '192.168.56.101',\n      desc: 'Simulation of an outdated Linux target featuring multiple intentional vulnerabilities, legacy service versions, and backdoors.',\n      services: {\n        ftp: 'vulnerable',    // vsftpd 2.3.4\n        ssh: 'vulnerable',    // OpenSSH 7.2\n        http: 'vulnerable',   // Apache 2.4.49\n        mysql: 'vulnerable',  // MySQL 5.5\n        rdp: 'disabled'\n      }\n    },\n    ubuntu: {\n      id: 'ubuntu',\n      name: 'Ubuntu Server 22.04 LTS (Hardened)',\n      ip: '192.168.56.102',\n      desc: 'A secure baseline server configuration. Unnecessary ports are blocked, and all running services are fully patched.',\n      services: {\n        ftp: 'disabled',\n        ssh: 'patched',       // OpenSSH 9.3\n        http: 'patched',      // nginx 1.24\n        mysql: 'patched',     // MySQL 8.0\n        rdp: 'disabled'\n      }\n    },\n    windows: {\n      id: 'windows',\n      name: 'Windows Server 2012 R2 (RDP Vuln)',\n      ip: '192.168.56.103',\n      desc: 'Legacy Windows server simulation exposing Remote Desktop (RDP) on port 3389 with BlueKeep vulnerability.',\n      services: {\n        ftp: 'disabled',\n        ssh: 'disabled',\n        http: 'disabled',\n        mysql: 'disabled',\n        rdp: 'vulnerable'     // Microsoft Terminal Services (BlueKeep)\n      }\n    },\n    custom: {\n      id: 'custom',\n      name: 'Custom Target (Configurable)',\n      ip: '192.168.56.200',\n      desc: 'Your custom configuration sandbox. Manually open, close, or patch individual services to test scanning outcomes.',\n      services: {\n        ftp: 'vulnerable',\n        ssh: 'vulnerable',\n        http: 'vulnerable',\n        mysql: 'vulnerable',\n        rdp: 'disabled'\n      }\n    }\n  };\n\n  /**\n   * Load active profiles from localStorage or load defaults\n   * @returns {Object} Target profiles\n   */\n  function getProfiles() {\n    try {\n      const stored = localStorage.getItem(STORAGE_KEY);\n      if (stored) {\n        return JSON.parse(stored);\n      }\n    } catch (e) {\n      console.error('Failed to load sandbox profiles:', e);\n    }\n    return _resetToDefaults();\n  }\n\n  /**\n   * Get a specific target profile by ID\n   * @param {string} id - Profile ID\n   * @returns {Object|null} Target profile\n   */\n  function getProfileById(id) {\n    const profiles = getProfiles();\n    return profiles[id] || null;\n  }\n\n  /**\n   * Update services state on a specific profile\n   * @param {string} id - Profile ID\n   * @param {Object} servicesState - Updated services configuration\n   */\n  function updateProfileServices(id, servicesState) {\n    const profiles = getProfiles();\n    if (profiles[id]) {\n      profiles[id].services = {\n        ...profiles[id].services,\n        ...servicesState\n      };\n      _save(profiles);\n      return profiles[id];\n    }\n    return null;\n  }\n\n  /**\n   * Check if a custom target IP matches one of the sandbox profiles\n   * @param {string} input - Target IP or identifier\n   * @returns {Object|null} Matched profile\n   */\n  function findProfileByIpOrName(input) {\n    if (!input) return null;\n    const profiles = getProfiles();\n    const cleanInput = input.trim().toLowerCase();\n\n    // Direct ID match\n    if (profiles[cleanInput]) return profiles[cleanInput];\n\n    // IP or name search\n    for (const key in profiles) {\n      const p = profiles[key];\n      if (p.ip === cleanInput || p.name.toLowerCase().includes(cleanInput)) {\n        return p;\n      }\n    }\n\n    // Default to custom if it looks like a sandbox IP\n    if (cleanInput.startsWith('192.168.56.')) {\n      return profiles.custom;\n    }\n\n    return null;\n  }\n\n  /* --- Internal --- */\n\n  function _save(profiles) {\n    try {\n      localStorage.setItem(STORAGE_KEY, JSON.stringify(profiles));\n    } catch (e) {\n      console.error('Failed to save sandbox profiles:', e);\n    }\n  }\n\n  function _resetToDefaults() {\n    _save(DEFAULT_PROFILES);\n    return DEFAULT_PROFILES;\n  }\n\n  return {\n    getProfiles,\n    getProfileById,\n    updateProfileServices,\n    findProfileByIpOrName,\n    resetToDefaults: _resetToDefaults\n  };\n})();\n"
