          "content": "{\n  \"name\": \"chatting-application\",\n  \"private\": true,\n  \"version\": \"0.0.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"vite\",\n    \"build\": \"tsc && vite build\",\n    \"preview\": \"vite preview\"\n  },\n  \"devDependencies\": {\n    \"typescript\": \"~6.0.2\",\n    \"vite\": \"^8.0.10\"\n  },\n  \"dependencies\": {\n    \"framer-motion\": \"^12.38.0\",\n    \"lucide-react\": \"^1.8.0\",\n    \"react\": \"^19.2.5\",\n    \"react-dom\": \"^19.2.5\",\n    \"socket.io-client\": \"^4.8.3\"\n  }\n}\n"
