          "language": "javascript",
          "content": "/**\n * Signature Database Module\n * Manages storage and operations for known malware hashes and pattern definitions.\n * Persists data to the browser's localStorage.\n */\n\nconst DEFAULT_SIGNATURES = [\n    {\n        id: \"sig_eicar_hash\",\n        name: \"EICAR Test File Hash\",\n        type: \"Hash\",\n        value: \"275a021bbfb6489e54d471899f7db9d1663fc695ec2fe2a2c4538aabf651fd0f\", // SHA-256\n        severity: \"Critical\",\n        classification: \"Standard Test File\",\n        description: \"Official EICAR Standard Anti-Virus Test File SHA-256 hash. Safe for validating scanning functionality.\"\n    },\n    {\n        id: \"sig_eicar_pattern\",\n        name: \"EICAR Test String Pattern\",\n        type: \"Byte-Pattern\",\n        value: \"EICAR-STANDARD-ANTIVIRUS-TEST-FILE\",\n        severity: \"Critical\",\n        classification: \"Standard Test File\",\n        description: \"Matches the text pattern within the EICAR test file, verifying string pattern scanning.\"\n    },\n    {\n        id: \"sig_wannacry_mock\",\n        name: \"Trojan.Ransom.WannaCry (Mock)\",\n        type: \"Hash\",\n        value: \"ed984a9a08e6900f0f18d7f26f296316279f64a4c62f277a837de1e604f5e718\", // SHA-256\n        severity: \"Critical\",\n        classification: \"Ransomware\",\n        description: \"Simulates the file hash of the notorious WannaCry cryptowriter payload.\"\n    },\n    {\n        id: \"sig_iloveyou_pattern\",\n        name: \"Worm.Script.ILOVEYOU (Mock)\",\n        type: \"Byte-Pattern\",\n        value: \"LOVE-LETTER-FOR-YOU.TXT.vbs\",\n        severity: \"High\",\n        classification: \"Worm\",\n        description: \"Matches script strings used in the reproduction script of the classic ILOVEYOU email worm.\"\n    },\n    {\n        id: \"sig_cobalt_pattern\",\n        name: \"Trojan.Spy.CobaltStrike (Mock)\",\n        type: \"Byte-Pattern\",\n        value: \"beacon.dll_cmd_exec\",\n        severity: \"Critical\",\n        classification: \"Trojan / Backdoor\",\n        description: \"Matches common string indicators associated with Cobalt Strike command-and-control beacons.\"\n    },\n    {\n        id: \"sig_adware_redirect\",\n        name: \"Adware.Generic.SearchRedirector\",\n        type: \"Byte-Pattern\",\n        value: \"search-redirector.js?affid=\",\n        severity: \"Medium\",\n        classification: \"Adware\",\n        description: \"Common query string utilized by browser hijacking adware to redirect searches to affiliate links.\"\n    },\n    {\n        id: \"sig_keylogger_hook\",\n        name: \"Spyware.Keylogger.GetAsyncKeyState\",\n        type: \"Byte-Pattern\",\n        value: \"GetAsyncKeyState\",\n        severity: \"High\",\n        classification: \"Spyware / Keylogger\",\n        description: \"Triggers when a file contains references to Windows API GetAsyncKeyState, indicative of keyboard hook logging.\"\n    }\n];\n\nclass SignatureDatabase {\n    constructor() {\n        this.storageKey = \"malware_signatures_db\";\n        this.init();\n    }\n\n    init() {\n        if (!localStorage.getItem(this.storageKey)) {\n            this.resetToDefaults();\n        }\n    }\n\n    getSignatures() {\n        try {\n            return JSON.parse(localStorage.getItem(this.storageKey)) || [];\n        } catch (e) {\n            console.error(\"Failed to parse signatures database. Resetting...\", e);\n            this.resetToDefaults();\n            return DEFAULT_SIGNATURES;\n        }\n    }\n\n    saveSignatures(signatures) {\n        localStorage.setItem(this.storageKey, JSON.stringify(signatures));\n    }\n\n    addSignature(sig) {\n        const signatures = this.getSignatures();\n        \n        // Generate simple ID if not present\n        const newSig = {\n            id: sig.id || \"sig_\" + Date.now(),\n            name: sig.name || \"Custom Signature\",\n            type: sig.type || \"Hash\",\n            value: sig.type === \"Hash\" ? sig.value.trim().toLowerCase() : sig.value.trim(),\n            severity: sig.severity || \"Medium\",\n            classification: sig.classification || \"Custom\",\n            description: sig.description || \"User added custom malware signature.\"\n        };\n\n        // If the signature is a hash, make sure it is normalized\n        if (newSig.type === \"Hash\") {\n            newSig.value = newSig.value.replace(/[^a-f0-9]/g, \"\"); // Strip non-hex\n        }\n\n        // Prevent duplicates\n        const exists = signatures.some(s => s.value === newSig.value && s.type === newSig.type);\n        if (exists) {\n            throw new Error(`A signature of type \"${newSig.type}\" with value \"${newSig.value}\" already exists.`);\n        }\n\n        signatures.push(newSig);\n        this.saveSignatures(signatures);\n        return newSig;\n    }\n\n    deleteSignature(id) {\n        let signatures = this.getSignatures();\n        const initialLen = signatures.length;\n        signatures = signatures.filter(sig => sig.id !== id);\n        \n        if (signatures.length === initialLen) {\n            return false;\n        }\n        \n        this.saveSignatures(signatures);\n        return true;\n    }\n\n    resetToDefaults() {\n        this.saveSignatures(DEFAULT_SIGNATURES);\n    }\n}\n\n// Export for browser use\nwindow.SignatureDB = new SignatureDatabase();\n"
