          "size": 6156,
          "language": "python",
          "content": "from flask import Flask, render_template, request, jsonify\r\nimport pandas as pd\r\nfrom sklearn.feature_extraction.text import TfidfVectorizer\r\nfrom sklearn.metrics.pairwise import cosine_similarity\r\nimport os\r\n\r\napp = Flask(__name__)\r\n\r\n# Use absolute paths to ensure the backend can access the datasets\r\nBASE_DIR = os.path.dirname(os.path.abspath(__file__))\r\nNETFLIX_PATH = os.path.join(BASE_DIR, 'data', 'netflix_dataset.csv')\r\nAMAZON_PATH = os.path.join(BASE_DIR, 'data', 'amazon_prime_titles.csv')\r\n\r\ndef load_data():\r\n    try:\r\n        # Load Netflix data\r\n        n_df = pd.read_csv(NETFLIX_PATH, encoding='utf-8')\r\n        n_df['platform'] = 'Netflix'\r\n        # Standardize column names: Category -> type, Type -> genres\r\n        n_df = n_df.rename(columns={\r\n            'Category': 'type', \r\n            'Title': 'title', \r\n            'Type': 'genres', \r\n            'Country': 'country', \r\n            'Description': 'desc'\r\n        })\r\n\r\n        # Load Amazon data\r\n        a_df = pd.read_csv(AMAZON_PATH, encoding='utf-8')\r\n        a_df['platform'] = 'Amazon Prime'\r\n        # Standardize column names: listed_in -> genres\r\n        a_df = a_df.rename(columns={\r\n            'type': 'type', \r\n            'title': 'title', \r\n            'listed_in': 'genres', \r\n            'country': 'country', \r\n            'description': 'desc'\r\n        })\r\n\r\n        # Combine relevant columns\r\n        cols = ['title', 'type', 'genres', 'country', 'desc', 'platform', 'rating']\r\n        \r\n        # Ensure all columns exist before concatenating\r\n        def prepare_df(df, platform_name):\r\n            df['platform'] = platform_name\r\n            # Fill missing columns with N/A\r\n            for col in cols:\r\n                if col not in df.columns:\r\n                    df[col] = 'N/A'\r\n            return df[cols]\r\n\r\n        # Prepare Netflix\r\n        n_df = n_df.rename(columns={\r\n            'Category': 'type', \r\n            'Title': 'title', \r\n            'Type': 'genres', \r\n            'Country': 'country', \r\n            'Description': 'desc',\r\n            'Rating': 'rating'\r\n        })\r\n        n_df = prepare_df(n_df, 'Netflix')\r\n\r\n        # Prepare Amazon\r\n        a_df = a_df.rename(columns={\r\n            'listed_in': 'genres', \r\n            'description': 'desc'\r\n        })\r\n        a_df = prepare_df(a_df, 'Amazon Prime')\r\n        \r\n        # Load Regional movies\r\n        regional_path = os.path.join(BASE_DIR, 'data', 'regional_movies.csv')\r\n        r_df = pd.DataFrame(columns=cols)\r\n        if os.path.exists(regional_path):\r\n            try:\r\n                r_df = pd.read_csv(regional_path, encoding='utf-8')\r\n                # If regional doesn't have rating, add it\r\n                if 'rating' not in r_df.columns:\r\n                    r_df['rating'] = '4.5' # Default for hand-picked regional data\r\n                r_df['platform'] = r_df['platform'] if 'platform' in r_df.columns else 'Popular'\r\n            except Exception as e:\r\n                print(f\"Error reading regional_movies.csv: {e}\")\r\n        \r\n        r_df = prepare_df(r_df, 'Popular')\r\n\r\n        # Combine\r\n        combined = pd.concat([n_df, a_df, r_df], ignore_index=True)\r\n        return combined\r\n    except Exception as e:\r\n        print(f\"Error loading datasets: {e}\")\r\n        return pd.DataFrame(columns=['title', 'type', 'genres', 'country', 'desc', 'platform', 'rating'])\r\n\r\ncombined_df = load_data()\r\n\r\nprint(\"Building TF-IDF Matrix...\")\r\ncombined_df['combined_features'] = combined_df['title'].fillna('') + ' ' + combined_df['genres'].fillna('') + ' ' + combined_df['desc'].fillna('')\r\ntfidf = TfidfVectorizer(stop_words='english')\r\ntfidf_matrix = tfidf.fit_transform(combined_df['combined_features'])\r\nprint(\"TF-IDF Matrix ready!\")\r\n\r\ndef get_unique_list(df, column):\r\n    if column not in df.columns:\r\n        return []\r\n    items = df[column].dropna().astype(str).str.split(',').explode().str.strip()\r\n    return sorted(list(set(i for i in items if i.lower() != 'n/a' and i != '')))\r\n\r\nUNIQUE_GENRES = get_unique_list(combined_df, 'genres')\r\nUNIQUE_LANGUAGES = get_unique_list(combined_df, 'country')\r\n\r\n@app.route('/', methods=['GET', 'POST'])\r\ndef index():\r\n    if request.method == 'POST':\r\n        data = request.get_json()\r\n        category = data.get('category')\r\n        genre = data.get('genre')\r\n        language = data.get('language')\r\n        search_text = data.get('search_text', '').strip()\r\n\r\n        filtered = combined_df.copy()\r\n\r\n        # Filter by Category\r\n        if category == 'Movie':\r\n            filtered = filtered[filtered['type'] == 'Movie']\r\n        elif category == 'Web Series' or category == 'TV Show':\r\n            filtered = filtered[filtered['type'] == 'TV Show']\r\n        elif category == 'Anime':\r\n            filtered = filtered[filtered['genres'].str.contains('Anime', case=False, na=False)]\r\n\r\n        # Filter by Genre\r\n        if genre:\r\n            filtered = filtered[filtered['genres'].str.contains(genre, case=False, na=False)]\r\n            \r\n# Recommender: TF-IDF for search_text\r\n        if search_text:\r\n            search_vec = tfidf.transform([search_text])\r\n            sim_scores = cosine_similarity(search_vec, tfidf_matrix).flatten()\r\n            filtered['sim_score'] = sim_scores[filtered.index]\r\n            filtered = filtered[filtered['sim_score'] > 0]\r\n            filtered = filtered.sort_values(by='sim_score', ascending=False)\r\n            if not filtered.empty:\r\n                filtered = filtered.head(10)\r\n        else:\r\n            if not filtered.empty:\r\n                result_size = min(10, len(filtered))\r\n                filtered = filtered.sample(n=result_size)\r\n\r\n        return jsonify(filtered.to_dict('records'))\r\n\r\n    return render_template('index.html', genres=UNIQUE_GENRES, languages=UNIQUE_LANGUAGES)\r\n\r\n@app.route('/health')\r\ndef health():\r\n    \"\"\"Health check for the frontend to verify connectivity.\"\"\"\r\n    return jsonify({\"status\": \"healthy\", \"message\": \"Backend connected!\"})\r\n\r\nif __name__ == '__main__':\r\n    # Listen on all interfaces (0.0.0.0) to solve potential firewall/port issues on desktop\r\n    app.run(host='0.0.0.0', port=5000, debug=True)"
